themeCSS:
.node rect {
  rx: 10px;
  ry: 10px;
  filter: none;
}
.cluster rect {
  rx: 14px;
  ry: 14px;
  filter: none;
}
.nodeLabel {
  font-weight: 500;
}
.cluster-label {
  font-weight: 600;
}
.edgeLabel {
  color: #475569;
  font-size: 14px;
}

.node.frontend rect { fill: #ecfdf5; stroke: #6ee7b7; } .node.frontend .nodeLabel { color: #064e3b; }
.node.runtime rect { fill: #eff6ff; stroke: #93c5fd; } .node.runtime .nodeLabel { color: #1e3a8a; }
.node.library rect { fill: #f5f3ff; stroke: #c4b5fd; } .node.library .nodeLabel { color: #4c1d95; }
.node.source rect { fill: #f8fafc; stroke: #cbd5e1; } .node.source .nodeLabel { color: #334155; }
.node.tool rect { fill: #fffbeb; stroke: #fcd34d; } .node.tool .nodeLabel { color: #78350f; }
.node.artifact rect { fill: #ecfdf5; stroke: #6ee7b7; } .node.artifact .nodeLabel { color: #064e3b; }
